const copy={es:{credibility:"15 años creando software · Proyectos en EE. UU. y México",aiexample:'Ejemplo: un asistente para tu equipo que responde preguntas con tus documentos internos.',automationexample:'Ejemplo: una venta registrada en tu CRM genera automáticamente un borrador de factura.',softwareexample:'Ejemplo: una herramienta interna para gestionar trabajos, cotizaciones y facturas en un solo lugar.',softwarefactory:"¿Tu operación ha crecido tanto que ya cuentas con desarrolladores internos? Ayudamos a tu equipo a incorporar IA en su trabajo diario para agilizar la programación, las pruebas y el mantenimiento.",intro:'SOFTWARE · AUTOMATIZACIÓN · IA',heroPitch:"Pon la IA a trabajar<br>para tu empresa.",lead:"Convierte el conocimiento de tu negocio en soluciones que te ayuden a ahorrar tiempo, reducir errores y mejorar tu operación.",talk:'Hablemos de tu proceso',portrait:'Ingeniería con propósito.',portrait2:'Tecnología que sí trabaja para ti.',aboutlabel:'UN POCO SOBRE MÍ',abouttitle:'De la idea a algo<br>que funciona.',aboutbody:"Llevo 15 años desarrollando software para proyectos en Estados Unidos y México. He trabajado en plataformas con cientos de miles de usuarios y en herramientas hechas a la medida de pequeñas y medianas empresas.",aboutbody2:"Hoy estoy aplicando IA a la automatización del desarrollo de software. Esa experiencia también guía cómo ayudo a otras empresas: entender el trabajo, encontrar oportunidades concretas y construir soluciones que se puedan medir.",years:'años creando software',experience:'experiencia en ambos mercados',serviceslabel:'CÓMO PUEDO AYUDARTE',servicestitle:'Mejores procesos.<br>Más posibilidades.',ai:'IA aplicada a tu empresa',aibody:'Identificamos dónde puede ayudarte la IA, elegimos herramientas y las integramos en tu operación. Desde organizar información y preparar documentos hasta apoyar a tu equipo en tareas diarias.',aitag1:'Casos de uso',aitag2:'Integración',aitag3:'Adopción',automation:'Automatización e integraciones',automationbody:'Conectamos las herramientas que ya usas para reducir la captura manual, generar reportes y dar seguimiento a procesos sin repetir el mismo trabajo todos los días.',software:"Software a medida con IA",softwarebody:"Creamos una fábrica de software automatizada con IA para que tu empresa pueda desarrollar y mejorar las herramientas que necesita sin ayuda externa.",contactlabel:'CONVERSEMOS',contacttitle:'¿Qué te gustaría<br><em>hacer mejor?</em>',contactbody:'Cuéntame de una tarea que se repite, un sistema que no se conecta o una idea que quieres explorar con IA.',whatsapp:'Hablemos por WhatsApp',save:'Guardar mi contacto',footer:'Software bien pensado. IA bien aplicada.',saved:'Contacto descargado. Ábrelo para agregarlo a tu agenda.',title:'Marcos Borunda — IA para empresas',description:'Ayudo a empresas a aplicar inteligencia artificial, automatizar procesos y crear software a medida. 15 años de experiencia.'},en:{credibility:"15 years building software · Projects in the U.S. & Mexico",aiexample:'Example: A team assistant that answers questions from your internal documents.',automationexample:'Example: A sale recorded in your CRM automatically creates an invoice draft.',softwareexample:'Example: An internal tool to manage jobs, quotes, and invoices in one place.',softwarefactory:"Has your business grown to the point where you have in-house developers? We help your team adopt AI in their daily work to streamline coding, testing, and maintenance.",intro:'SOFTWARE · AUTOMATION · AI',heroPitch:"Put AI to work<br>for your business.",lead:"Turn your business knowledge into solutions that help you save time, reduce errors, and improve your operations.",talk:'Discuss your process',portrait:'Engineering with purpose.',portrait2:'Technology that works for you.',aboutlabel:'A LITTLE ABOUT ME',abouttitle:'From an idea to<br>something that works.',aboutbody:"I’ve spent 15 years building software for projects in the United States and Mexico. My experience spans platforms with hundreds of thousands of users and custom tools for small and medium-sized businesses.",aboutbody2:"Today, I’m applying AI to automate software development. That experience also shapes how I help other businesses: understand the work, identify concrete opportunities, and build solutions with measurable results.",years:'years building software',experience:'experience in both markets',serviceslabel:'HOW I CAN HELP',servicestitle:'Better processes.<br>More possibilities.',ai:'AI applied to your business',aibody:'We identify where AI can help, choose the right tools, and integrate them into your operations. From organizing information and preparing documents to helping your team with everyday tasks.',aitag1:'Use cases',aitag2:'Integration',aitag3:'Adoption',automation:'Automation & integrations',automationbody:'We connect the tools you already use to reduce manual data entry, generate reports, and follow up on processes without repeating the same work every day.',software:"AI-powered custom software",softwarebody:"We build an AI-powered automated software factory so your business can develop and improve the tools it needs without outside help.",contactlabel:'LET’S TALK',contacttitle:'What would you like<br><em>to do better?</em>',contactbody:'Tell me about a recurring task, a system that doesn’t connect, or an idea you’d like to explore with AI.',whatsapp:'Let’s talk on WhatsApp',save:'Save my contact',footer:'Thoughtful software. Practical AI.',saved:'Contact downloaded. Open it to add it to your address book.',title:'Marcos Borunda — AI for business',description:'I help businesses apply AI, automate processes, and build custom software. 15 years of experience.'}};
const contact={name:'Marcos Borunda',phone:'+526142409981'};
let language=document.documentElement.lang==='es'?'es':'en';
function setLanguage(lang,persist=false){language=lang;document.documentElement.lang=lang;document.querySelectorAll('[data-t]').forEach(el=>{el.innerHTML=copy[lang][el.dataset.t]});document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===lang)));document.title=copy[lang].title;document.querySelector('meta[name=description]').content=copy[lang].description;document.getElementById('contact-status').textContent='';if(persist)try{localStorage.setItem('mb-language',lang)}catch{}}
document.querySelectorAll('[data-lang]').forEach(el=>el.addEventListener('click',()=>setLanguage(el.dataset.lang,true)));
if(contact.phone){const link=document.getElementById('whatsapp');link.href='https://wa.me/'+contact.phone.replace(/\D/g,'');link.removeAttribute('aria-disabled');link.target='_blank';link.rel='noopener noreferrer'}
document.getElementById('save-contact').addEventListener('click',()=>{const lines=['BEGIN:VCARD','VERSION:3.0','N:Borunda;Marcos;;;','FN:Marcos Borunda','TITLE:Software / Automation / AI'];if(contact.phone)lines.push('TEL;TYPE=CELL:'+contact.phone);lines.push('END:VCARD');const url=URL.createObjectURL(new Blob([lines.join('\r\n')+'\r\n'],{type:'text/vcard;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Marcos-Borunda.vcf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('contact-status').textContent=copy[language].saved});
document.getElementById('year').textContent=new Date().getFullYear();setLanguage(language);
